package br.com.tapeteskalke.entity; import jakarta.persistence.*; import java.math.BigDecimal; import lombok.Getter; import lombok.Setter;
@Entity @Table(name="venda_item") @Getter @Setter public class VendaItem { @Id @Column(length=38) private String id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="id_venda",nullable=false) private Venda venda; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="id_produto",nullable=false) private Produto produto; @Column(name="produto_nome_snapshot",nullable=false) private String produtoNomeSnapshot; @Column(name="unidade_medida_snapshot",nullable=false) private String unidadeMedidaSnapshot; @Column(nullable=false,precision=15,scale=3) private BigDecimal quantidade; @Column(name="preco_unitario",nullable=false,precision=15,scale=2) private BigDecimal precoUnitario; @Column(nullable=false,precision=15,scale=2) private BigDecimal subtotal; @Column(name="custo_unitario",precision=15,scale=2) private BigDecimal custoUnitario; @PrePersist void id(){if(id==null)id=java.util.UUID.randomUUID().toString();} }